const { useState, useEffect, useRef, useCallback, useMemo } = React;

const PARTICIPANTS = [
  { id: "chregi", name: "Chregi", img: "data:image/jpeg;base64," },
  { id: "reto",   name: "Reto",   img: "data:image/jpeg;base64," },
  { id: "nick",   name: "Nick",   img: "data:image/jpeg;base64," },
  { id: "glen",   name: "Glen",   img: "data:image/jpeg;base64," },
  { id: "nora",   name: "Nora",   img: "data:image/jpeg;base64," },
  { id: "tine",   name: "Tine",   img: "data:image/jpeg;base64," },
  { id: "matthu", name: "Mätthu", img: "data:image/jpeg;base64," },
  { id: "ursi",   name: "Ursi",   img: "data:image/jpeg;base64," },
  { id: "alex",   name: "Alex",   img: "data:image/jpeg;base64," },
  { id: "naedi",  name: "Nädi",   img: "data:image/jpeg;base64," },
];
const LOGO_IMG = "data:image/jpeg;base64,";
const ADMIN_IMG = "data:image/jpeg;base64,";
const PWD = "Nesslergraben";
const LS_KEY = "homiesCupMallorca2026_state_v1";
const INSTALL_DISMISS_KEY = "homiesCupMallorca2026_installDismissed";

const byId = Object.fromEntries(PARTICIPANTS.map(p => [p.id, p]));

function pairKey(a, b) { return [a, b].sort().join("|"); }

function shuffleArr(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function backtrackPairs(remaining, forbidden, top4) {
  if (remaining.length === 0) return [];
  const a = remaining[0];
  const rest = remaining.slice(1);
  const candidates = shuffleArr(rest);
  for (const b of candidates) {
    if (forbidden.has(pairKey(a, b))) continue;
    if (top4 && top4.has(a) && top4.has(b)) continue;
    const nextRemaining = rest.filter(x => x !== b);
    const sub = backtrackPairs(nextRemaining, forbidden, top4);
    if (sub) return [[a, b], ...sub];
  }
  return null;
}

function computeForbidden(rounds, lookback) {
  const set = new Set();
  rounds.slice(-lookback).forEach(r => r.pairs.forEach(([a, b]) => set.add(pairKey(a, b))));
  return set;
}

function computeTotals(rounds) {
  const totals = Object.fromEntries(PARTICIPANTS.map(p => [p.id, 0]));
  rounds.forEach(r => {
    if (!r.points) return;
    r.pairs.forEach(([a, b], i) => {
      const entry = r.points[i];
      if (Array.isArray(entry)) {
        totals[a] += Number(entry[0]) || 0;
        totals[b] += Number(entry[1]) || 0;
      } else {
        const pts = Number(entry) || 0;
        totals[a] += pts;
        totals[b] += pts;
      }
    });
  });
  return totals;
}

function computeTop4(totals) {
  return new Set(
    Object.keys(totals)
      .sort((a, b) => totals[b] - totals[a])
      .slice(0, 4)
  );
}

function performDraw(rounds, finalPhaseEnabled) {
  const ids = PARTICIPANTS.map(p => p.id);
  const totals = computeTotals(rounds);
  const top4 = finalPhaseEnabled ? computeTop4(totals) : null;

  let forbidden = computeForbidden(rounds, 2);
  let res = backtrackPairs(shuffleArr(ids), forbidden, top4);
  if (res) return res;

  forbidden = computeForbidden(rounds, 1);
  res = backtrackPairs(shuffleArr(ids), forbidden, top4);
  if (res) return res;

  if (!finalPhaseEnabled) {
    res = backtrackPairs(shuffleArr(ids), new Set(), null);
    if (res) return res;
  }

  res = backtrackPairs(shuffleArr(ids), new Set(), top4);
  return res;
}

function defaultState() {
  return { version: 1, rounds: [], finalPhaseEnabled: false };
}

function countTrailingFinalRounds(rounds) {
  let count = 0;
  for (let i = rounds.length - 1; i >= 0; i--) {
    if (rounds[i].finalPhase) count++;
    else break;
  }
  return count;
}

function loadInitialState() {
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && Array.isArray(parsed.rounds)) return parsed;
    }
  } catch (e) {}
  return defaultState();
}

function Avatar({ id, size }) {
  const p = byId[id];
  if (!p) return null;
  return (
    <img
      src={p.img}
      alt={p.name}
      style={{
        width: size, height: size, borderRadius: "50%", objectFit: "cover",
        border: "3px solid var(--ink)", background: "var(--white)", flexShrink: 0,
      }}
    />
  );
}

function TeamPairImgs({ a, b, size }) {
  return (
    <div className="team-pair-imgs">
      <img src={byId[a].img} alt={byId[a].name} style={size ? { width: size, height: size } : undefined} />
      <span className="team-amp">&amp;</span>
      <img src={byId[b].img} alt={byId[b].name} style={size ? { width: size, height: size } : undefined} />
    </div>
  );
}

function useSwirlPositions(active, count) {
  const [positions, setPositions] = useState([]);
  const containerRef = useRef({ w: 900, h: 460 });

  const randomPos = useCallback(() => {
    const w = containerRef.current.w, h = containerRef.current.h;
    const margin = 60;
    return {
      top: margin + Math.random() * Math.max(1, h - margin * 2),
      left: margin + Math.random() * Math.max(1, w - margin * 2),
      rot: Math.random() * 40 - 20,
    };
  }, []);

  useEffect(() => {
    if (!active) return;
    setPositions(Array.from({ length: count }, randomPos));
    const interval = setInterval(() => {
      setPositions(Array.from({ length: count }, randomPos));
    }, 650);
    return () => clearInterval(interval);
  }, [active, count, randomPos]);

  return [positions, containerRef];
}

function DrawOverlay({ finalPhaseEnabled, onDone }) {
  const [phase, setPhase] = useState("swirl");
  const [count, setCount] = useState(3);
  const [positions, containerRef] = useSwirlPositions(phase === "swirl" || phase === "countdown", PARTICIPANTS.length);
  const stageRef = useRef(null);

  useEffect(() => {
    if (stageRef.current) {
      containerRef.current = { w: stageRef.current.clientWidth, h: stageRef.current.clientHeight };
    }
  }, [containerRef]);

  useEffect(() => {
    const t1 = setTimeout(() => setPhase("countdown"), 2200);
    return () => clearTimeout(t1);
  }, []);

  useEffect(() => {
    if (phase !== "countdown") return;
    if (count <= 0) {
      const t = setTimeout(() => onDone(), 350);
      return () => clearTimeout(t);
    }
    const t = setTimeout(() => setCount(c => c - 1), 700);
    return () => clearTimeout(t);
  }, [phase, count, onDone]);

  const confetti = useMemo(() => Array.from({ length: 26 }, (_, i) => ({
    id: i,
    left: Math.random() * 100,
    top: Math.random() * 100,
    size: 5 + Math.random() * 8,
    delay: Math.random() * 2,
  })), []);

  return (
    <div className="overlay" ref={stageRef}>
      {confetti.map(c => (
        <div key={c.id} className="confetti-dot" style={{
          left: c.left + "%", top: c.top + "%", width: c.size, height: c.size,
          animation: `pulse 1.6s ease-in-out ${c.delay}s infinite`
        }} />
      ))}
      {PARTICIPANTS.map((p, i) => {
        const pos = positions[i] || { top: 200, left: 200, rot: 0 };
        return (
          <img
            key={p.id}
            className="swirl-avatar"
            src={p.img}
            alt={p.name}
            style={{ top: pos.top, left: pos.left, transform: `rotate(${pos.rot}deg)` }}
          />
        );
      })}
      {phase === "countdown" && (
        <>
          <div className="countdown-number">{count > 0 ? count : "🎉"}</div>
          <div className="overlay-caption">Die Teams werden ausgelost{finalPhaseEnabled ? " · Finalphase" : ""}</div>
        </>
      )}
      {phase === "swirl" && (
        <div className="overlay-caption">Alle durcheinander würfeln…</div>
      )}
      <style>{`@keyframes pulse { 0%,100% { opacity: 0.35; transform: scale(1);} 50% { opacity: 0.9; transform: scale(1.4);} }`}</style>
    </div>
  );
}

