function isIos() {
  return /iphone|ipad|ipod/i.test(window.navigator.userAgent) ||
    (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
}
function isStandalone() {
  return window.matchMedia("(display-mode: standalone)").matches || window.navigator.standalone === true;
}

function InstallBanner() {
  const [deferredPrompt, setDeferredPrompt] = useState(null);
  const [dismissed, setDismissed] = useState(() => {
    try { return localStorage.getItem(INSTALL_DISMISS_KEY) === "1"; } catch (e) { return false; }
  });

  useEffect(() => {
    function handler(e) {
      e.preventDefault();
      setDeferredPrompt(e);
    }
    window.addEventListener("beforeinstallprompt", handler);
    return () => window.removeEventListener("beforeinstallprompt", handler);
  }, []);

  if (isStandalone() || dismissed) return null;
  if (!deferredPrompt && !isIos()) return null;

  function dismiss() {
    setDismissed(true);
    try { localStorage.setItem(INSTALL_DISMISS_KEY, "1"); } catch (e) {}
  }

  async function install() {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      await deferredPrompt.userChoice;
      setDeferredPrompt(null);
      dismiss();
    }
  }

  return (
    <div className="install-banner">
      {deferredPrompt ? (
        <>
          <span>📲 Homies Cup zum Homescreen hinzufügen für Offline-Zugriff?</span>
          <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
            <button onClick={install}>Installieren</button>
            <button className="close-x" onClick={dismiss} aria-label="Schliessen">×</button>
          </div>
        </>
      ) : (
        <>
          <span>📲 Für Offline-Zugriff: Teilen-Symbol antippen → „Zum Home-Bildschirm"</span>
          <button className="close-x" onClick={dismiss} aria-label="Schliessen">×</button>
        </>
      )}
    </div>
  );
}

function App() {
  const [state, setState] = useState(loadInitialState);
  const [uiPhase, setUiPhase] = useState("home");
  const [pendingPairs, setPendingPairs] = useState(null);
  const [showTable, setShowTable] = useState(false);
  const [showReset, setShowReset] = useState(false);
  const [toast, setToast] = useState("");
  const fileInputRef = useRef(null);

  useEffect(() => {
    try { localStorage.setItem(LS_KEY, JSON.stringify(state)); } catch (e) {}
  }, [state]);

  const persist = useCallback((newState) => {
    setState(newState);
  }, []);

  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(""), 2600);
    return () => clearTimeout(t);
  }, [toast]);

  const rounds = state.rounds;
  const currentRound = rounds.length ? rounds[rounds.length - 1] : null;
  const hasPendingRound = !!currentRound && currentRound.points === null;
  const totals = useMemo(() => computeTotals(rounds), [rounds]);
  const nextRoundNumber = rounds.length + (hasPendingRound ? 0 : 1);
  const trailingFinalRounds = useMemo(() => countTrailingFinalRounds(rounds), [rounds]);
  const tournamentFinished = state.finalPhaseEnabled && !hasPendingRound && trailingFinalRounds >= 2;

  function startDraw() {
    const pairs = performDraw(rounds, state.finalPhaseEnabled);
    setPendingPairs(pairs);
    setUiPhase("drawing");
  }

  function handleDrawDone() {
    const newRound = {
      id: rounds.length + 1,
      pairs: pendingPairs,
      points: null,
      finalPhase: state.finalPhaseEnabled,
    };
    const newState = { ...state, rounds: [...rounds, newRound] };
    persist(newState);
    setUiPhase("reveal");
  }

  function handleRevealContinue() {
    setUiPhase("home");
    setPendingPairs(null);
  }

  function handleSavePoints(pointsArr) {
    const newRounds = rounds.slice();
    newRounds[newRounds.length - 1] = { ...currentRound, points: pointsArr };
    persist({ ...state, rounds: newRounds });
    setToast(`Runde ${currentRound.id} gespeichert!`);
  }

  function toggleFinalPhase() {
    persist({ ...state, finalPhaseEnabled: !state.finalPhaseEnabled });
  }

  async function handleExport() {
    const data = JSON.stringify(state, null, 2);
    const filename = "homies-cup-mallorca-2026-spielstand.json";

    try {
      const file = new File([data], filename, { type: "application/json" });
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ files: [file], title: filename });
        setToast("Spielstand geteilt!");
        return;
      }
    } catch (e) {
      if (e && e.name === "AbortError") return; // Nutzer hat Teilen abgebrochen
    }

    try {
      const blob = new Blob([data], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url; a.download = filename;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      setToast("Spielstand exportiert!");
    } catch (e2) {
      setToast("Export leider fehlgeschlagen.");
    }
  }

  function handleImportFile(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const parsed = JSON.parse(reader.result);
        if (parsed && Array.isArray(parsed.rounds)) {
          persist({ version: 1, rounds: parsed.rounds, finalPhaseEnabled: !!parsed.finalPhaseEnabled });
          setUiPhase("home");
          setToast("Spielstand geladen!");
        } else {
          setToast("Diese Datei ist kein gültiger Spielstand.");
        }
      } catch (err) {
        setToast("Datei konnte nicht gelesen werden.");
      }
    };
    reader.readAsText(file);
    e.target.value = "";
  }

  function handleReset() {
    persist(defaultState());
    setShowReset(false);
    setUiPhase("home");
    setPendingPairs(null);
    setToast("Neustart durchgeführt.");
  }

  return (
    <div className="app-shell">
      <InstallBanner />
      <header className="masthead">
        <div className="stripe-bg stripe-edge"></div>
        <div className="stripe-bg stripe-edge bottom"></div>
        <img className="logo-badge" src={LOGO_IMG} alt="Homies Cup Mallorca 2026" />
        <div className="titles">
          <h1>HOMIES CUP MALLORCA 2026</h1>
          <div className="sub">FAMILIEN-AUSLOSUNG</div>
        </div>
        <div className="round-pill">
          {rounds.length === 0 ? "Vor Runde 1" : hasPendingRound ? `Runde ${currentRound.id} läuft` : `${rounds.length} Runde${rounds.length === 1 ? "" : "n"} gespielt`}
        </div>
        <button className="btn btn-gold" style={{ flexShrink: 0 }} onClick={() => setShowReset(true)}>↺ Neustart</button>
      </header>

      <div className="layout">
        <div>
          <div className="panel">
            <h2><small>Protokoll</small>Rundenverlauf</h2>
            {rounds.length === 0 ? (
              <p className="log-empty">Noch keine Runde ausgelost.</p>
            ) : (
              <ul className="log-list">
                {rounds.slice().reverse().map(r => (
                  <li className="log-item" key={r.id}>
                    <div className="log-round">Runde {r.id}{r.finalPhase ? " · Finalphase" : ""}{r.points === null ? " · offen" : ""}</div>
                    <div className="log-pairs">
                      {r.pairs.map(([a, b], i) => (
                        <span key={i}><b>{byId[a].name}</b> &amp; <b>{byId[b].name}</b>{i < r.pairs.length - 1 ? " · " : ""}</span>
                      ))}
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </div>

          <div className="panel controls-panel">
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, marginBottom: 14 }}>
              <h2 style={{ margin: 0 }}><small>Einstellungen</small>Turnier</h2>
              <img
                src={ADMIN_IMG}
                alt="Admin"
                style={{ width: 56, height: 56, borderRadius: "50%", objectFit: "cover", border: "3px solid var(--gold)", flexShrink: 0 }}
              />
            </div>
            <label className="toggle-row">
              <input type="checkbox" checked={state.finalPhaseEnabled} onChange={toggleFinalPhase} />
              <span className="toggle-text">
                <strong>Finalphase</strong>
              </span>
            </label>
            <div className="btn-row">
              <button className="btn btn-ink btn-full" onClick={() => setShowTable(true)}>🔒 Tabelle</button>
            </div>
            <div className="btn-row">
              <button className="btn btn-outline" onClick={handleExport}>⬇ Exportieren</button>
              <button className="btn btn-outline" onClick={() => fileInputRef.current && fileInputRef.current.click()}>⬆ Importieren</button>
            </div>
            <input ref={fileInputRef} type="file" accept="application/json" className="hidden-file-input" onChange={handleImportFile} />
            <div className="btn-row">
              <button className="btn btn-danger" onClick={() => setShowReset(true)}>↺ Neustart</button>
            </div>
          </div>
        </div>

        <div className="panel" style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
          {hasPendingRound ? (
            <PointsEntryCard round={currentRound} onSave={handleSavePoints} />
          ) : tournamentFinished ? (
            <FinishedCard onShowTable={() => setShowTable(true)} />
          ) : (
            <DrawCard roundNumber={nextRoundNumber} onStart={startDraw} />
          )}
        </div>
      </div>

      <p className="footer-note">10 Homies · 5 Teams pro Runde · viel Glück auf Mallorca! 🏆</p>

      {uiPhase === "drawing" && (
        <DrawOverlay finalPhaseEnabled={state.finalPhaseEnabled} onDone={handleDrawDone} />
      )}
      {uiPhase === "reveal" && currentRound && (
        <RevealOverlay pairs={currentRound.pairs} roundNumber={currentRound.id} onContinue={handleRevealContinue} />
      )}
      {showTable && (
        <StandingsModal
          rounds={rounds}
          totals={totals}
          onUpdateRounds={(newRounds) => persist({ ...state, rounds: newRounds })}
          onClose={() => setShowTable(false)}
        />
      )}
      {showReset && (
        <ConfirmModal
          title="Neustart – bist du sicher?"
          text="Alle Runden, Paarungen und Punkte werden unwiderruflich gelöscht."
          onConfirm={handleReset}
          onCancel={() => setShowReset(false)}
        />
      )}
      {toast && <div className="toast">{toast}</div>}
    </div>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<App />);
